  ('9b6b76f5-3386-4246-a022-e9e48804b8cd', '19b911dd-2869-4e61-86c4-6ab03f15bf16', null, 'topic'::public.curated_course_node_type, 'Atomic Structure and Bonding', 'Materials behavior begins at the atomic scale. This topic explains how electrons, bonds, and atomic arrangements shape stiffness, melting temperature, conductivity, and chemical stability.', 0),
